// Published games are immutable except for a paused, reviewed prize revision.
const cloneOperation=value=>value===undefined?undefined:JSON.parse(JSON.stringify(value));
function gameLocked(){return state.published||state.ended}
function prizeRevisionEditing(){return state.published&&state.paused&&!state.ended&&!!state.settings.operationBaseline}
function operationConfig(){return cloneOperation({rewards:rewards(),pickup:state.settings.pickup||state.basic.place||'안내 데스크',approval:state.settings.reviewApproval,approved:state.approved})}
function startPrizeRevision(){if(!state.published||!state.paused||state.ended)return toast('일시중지한 행사에서 경품 설정을 변경할 수 있습니다.');if(!state.settings.operationBaseline)state.settings.operationBaseline=operationConfig();state.editorTab='경품';retainEvent();go('prizes')}
function cancelPrizeRevision(){const baseline=state.settings.operationBaseline;if(!baseline)return;state.settings.rewards=cloneOperation(baseline.rewards);state.settings.pickup=baseline.pickup;state.settings.reviewApproval=cloneOperation(baseline.approval);state.approved=baseline.approved;delete state.settings.operationBaseline;state.prizeError=false;retainEvent();go('operate');toast('변경을 취소하고 기존 설정으로 돌아왔습니다.')}
function operationHistory(){return state.settings.operationHistory||(state.settings.operationHistory=[])}
function addPrizeStock(index,amount){if(!state.published||state.ended||state.settings.operationBaseline)return false;const p=rewards()[index];if(!p||p.quantity==='무제한'||!Number.isInteger(amount)||amount<=0)return false;const before=operationConfig(),wasApproved=approvalCurrent();p.quantity=Number(p.quantity)+amount;if(wasApproved)state.settings.reviewApproval.signature=approvalSignature();operationHistory().push({type:'수량 추가',time:new Date().toISOString(),before,after:operationConfig()});retainEvent();return true}
function stockModal(){qaModalOpener=document.activeElement;app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="stock-title"><div class="panel-head"><h2 id="stock-title">경품 수량 추가</h2><button data-qa-close aria-label="닫기">${uiIcon('close')}</button></div><div class="field"><label for="stock-prize">경품</label><select id="stock-prize">${rewards().map((p,i)=>p.quantity==='무제한'?'':`<option value="${i}">${esc(p.name)} · 총 ${p.quantity}개</option>`).join('')}</select></div><div class="field"><label for="stock-amount">추가 수량</label><input id="stock-amount" type="number" min="1" step="1" placeholder="추가할 수량"></div><p class="mini-label">경품 종류·확률·지급 방식은 유지됩니다.</p><button class="btn" data-operation="stock-save">추가</button></section></div>`);bind();activateModal()}
const operationalEditor=editor;editor=function(prizes=false){let h=operationalEditor(prizes);if(!gameLocked())return h;const editable=prizes&&prizeRevisionEditing();h=h.replace(/<a[^>]*href="#templates"[^>]*>템플릿 변경<\/a>/g,'').replace(/<button[^>]*data-pick-template[^>]*>[\s\S]*?<\/button>/g,'').replace(/<button[^>]*data-action="to-review"[^>]*>[\s\S]*?<\/button>/g,editable?'<button class="btn" data-action="to-review">변경 검토 요청</button>':'');if(!editable)h=h.replace(/<button[^>]*data-action="save"[^>]*>[\s\S]*?<\/button>/g,'').replace(/<button[^>]*data-studio="undo"[^>]*>[\s\S]*?<\/button>/g,'');const notice=editable?'<div class="operation-notice">경품 설정 변경 · 일시중지 중<button class="text-link" data-operation="cancel">변경 취소</button></div>':statusNotice('게시된 게임','게시가 완료된 게임은 조회만 가능합니다.','<a class="btn secondary" href="#operate">운영 화면으로</a>');return h.replace('<div class="editor-tabs">',notice+'<div class="editor-tabs">')};
const operationalOperate=operate;operate=function(){let h=operationalOperate();const panel=`<section class="panel operation-prizes"><div class="panel-head"><h2>경품 운영</h2><div class="inline">${!state.ended&&!state.settings.operationBaseline?'<button class="btn secondary" data-operation="stock">수량 추가</button>':''}${state.paused&&!state.ended?`<button class="btn secondary" data-operation="revise">${state.settings.operationBaseline?'변경 이어서 수정':'경품 설정 변경'}</button>`:''}</div></div>${prizeSummary()}${state.settings.operationBaseline?`<div class="operation-notice">${approvalCurrent()?'변경 확정 완료':'경품 변경 검토 필요'}<div class="inline"><a class="text-link" href="#review">변경 검토</a><button class="text-link" data-operation="cancel">변경 취소</button></div></div>`:!state.ended?'<p class="mini-label mt">경품 종류·확률·지급 방식은 일시중지 후 변경할 수 있습니다.</p>':''}${operationHistory().length?`<details class="mt"><summary>변경 이력 ${operationHistory().length}건</summary>${operationHistory().map(v=>`<div class="operation-history"><strong>${esc(v.type)}</strong><small>${new Date(v.time).toLocaleString('ko-KR')}</small><p>${v.before.rewards.map(p=>esc(p.name)+' '+esc(p.quantity)).join(' · ')} → ${v.after.rewards.map(p=>esc(p.name)+' '+esc(p.quantity)).join(' · ')}</p></div>`).join('')}</details>`:''}</section>`;return h.replace(/<section class="panel"><div class="panel-head"><h2>경품 잔여 수량<\/h2>[\s\S]*?<\/section>/,panel)};
const operationalReview=review;review=function(){let h=operationalReview();if(prizeRevisionEditing())h=h.replace('브랜드 게임 검토','경품 변경 검토').replace(/<button[^>]*data-action="to-publish"[^>]*>[\s\S]*?<\/button>/,'<button class="btn" data-action="pause">변경 적용 후 재개</button>').replace('현재 시안과 경품 설정이 확정되었습니다.','변경된 경품 설정이 확정되었습니다. 재개 후 참여부터 적용됩니다.');return h};
const operationalBrandReview=brandReview;brandReview=function(){let h=operationalBrandReview();if(prizeRevisionEditing())h=h.replace('게임 확정','경품 변경 확정').replace(/<a class="btn" href="#publish">게시 준비로<\/a>/,'');return h};
const operationalAction=action;action=function(a,n){if(gameLocked()&&!prizeRevisionEditing()&&['save','to-review','template','generate','apply','undo','approve','pay'].includes(a))return toast('게시된 게임은 읽기 전용입니다.');if(a==='end'&&state.settings.operationBaseline)cancelPrizeRevision();if(a==='pause'&&state.paused&&state.settings.operationBaseline){if(!approvalCurrent())return toast('변경된 경품 설정을 고객이 확정한 뒤 재개해주세요.');const before=state.settings.operationBaseline;operationHistory().push({type:'경품 변경',time:new Date().toISOString(),before,after:operationConfig()});delete state.settings.operationBaseline}if(a==='participate'||a==='spin'){if(state.paused||state.ended)return toast(state.ended?'종료된 행사입니다.':'일시중지 중인 행사입니다.')}operationalAction(a,n);if(a==='pause'&&route()!=='operate')go('operate')};
const operationalStudioAction=studioAction;studioAction=function(a){if(gameLocked())return toast('게시된 게임은 읽기 전용입니다.');operationalStudioAction(a)};
const operationalLayerChange=changeLayer;changeLayer=function(key,value){if(!gameLocked())operationalLayerChange(key,value)};
const operationalReorder=reorderLayer;reorderLayer=function(from,to){if(!gameLocked())operationalReorder(from,to)};
const operationalBind=bind;bind=function(){operationalBind();if(gameLocked()&&['editor','prizes','game-draft'].includes(route())){const editable=route()==='prizes'&&prizeRevisionEditing();app.querySelectorAll('.tool-body input,.tool-body textarea,.tool-body select,.tool-body button,.chat-tools textarea,.chat-tools [data-studio],.setting-form input,.setting-form select,.setting-form textarea,.setting-form button').forEach(n=>{if(editable&&(n.matches?.('[data-reward],#pickup-location,[data-action="save"]')))return;n.disabled=true;n.oninput=null;n.onchange=null;n.onkeydown=null});app.querySelectorAll('[data-togglelayer]').forEach(n=>{n.disabled=true;n.onclick=null});app.querySelectorAll('[data-drag-layer]').forEach(n=>{n.draggable=false;n.ondragstart=null;n.onkeydown=null});app.querySelectorAll('.layer-item').forEach(n=>{n.ondrop=null;n.ondragover=null})}app.querySelectorAll('[data-operation]').forEach(n=>n.onclick=()=>{const a=n.dataset.operation;if(a==='revise')startPrizeRevision();if(a==='cancel')cancelPrizeRevision();if(a==='stock')stockModal();if(a==='stock-save'){const i=Number(document.getElementById('stock-prize').value),amount=Number(document.getElementById('stock-amount').value);if(!addPrizeStock(i,amount))return toast('추가 수량을 양의 정수로 입력해주세요.');closeQaModal();render();toast('경품 수량을 추가했습니다.')}})};
const operationalMobile=mobile;mobile=function(mode){if((state.paused||state.ended)&&['start','game'].includes(mode))return `<main class="mobile-outer">${backButton()}<section class="phone operation-participant"><h2>${state.ended?'행사가 종료되었습니다.':'잠시 참여를 중단했습니다.'}</h2><p>${state.ended?'참여해주셔서 감사합니다.':'행사 재개 후 다시 참여해주세요.'}</p></section></main>`;return operationalMobile(mode)};
const clearerPassHome=home;home=function(){return clearerPassHome().replace('이번 달 행사 패스 <strong>2건</strong>','이번 달 행사 패스 사용 <strong>2건</strong>')};
const clearerPassShell=shell;shell=function(body){return clearerPassShell(body).replace('<dt>이번 달 행사 패스</dt>','<dt>이번 달 패스 사용</dt>')};
render();
